import{_ as e}from"./plugin-vue_export-helper-c27b6911.js";import{o as a,c as l,d as o}from"./app-be1fcd84.js";const c={},r=o('<h3 id="parallel" tabindex="-1"><a class="header-anchor" href="#parallel" aria-hidden="true">#</a> parallel</h3><ul><li>ブール値</li></ul><p>同じ対象で再生中の他のアニメーションと並行して再生します。</p><p>通常、同じ対象に新しい <code>setTransform</code> <code>setAnimation</code> <code>setTempAnimation</code> を実行すると、その対象で再生中のアニメーションは中断されます。<code>-parallel</code> を付けると、新しいアニメーションは既存のアニメーションを中断せず、同時に再生されます。その後に <code>-parallel</code> なしで実行したアニメーションは、並行アニメーションを含め、再生中のアニメーションをすべて中断します。</p><p>並行するアニメーションは、それぞれ異なる属性を変更してください。複数の並行アニメーションが同じ属性を変更すると、結果は予測できません。<code>-parallel</code> を使うと、アニメーションは記述した属性のみを変更します。</p>',5),t=[r];function d(n,p){return a(),l("div",null,t)}const _=e(c,[["render",d],["__file","parallel.html.vue"]]);export{_ as default};
